<?php
defined( 'ABSPATH' ) || exit;
class Digitalisimo_Integrations_SEO_AI_Entities_Tools {
	public static function init() { add_action( 'admin_menu', array( __CLASS__, 'menu' ), 35 ); }
	public static function menu() { add_submenu_page( 'digitalisimo', 'SEO AI · Entidades', 'SEO AI · Entidades', 'manage_options', 'digitalisimo-seo-ai-entities', array( __CLASS__, 'page' ) ); }
	public static function page() { if ( ! current_user_can( 'manage_options' ) ) return; $g = function( $key ) { return (string) Digitalisimo_Integrations_Settings::get( $key ); }; $org = $g( 'seo_organization_name' ) ?: get_bloginfo( 'name' ); $site = $g( 'seo_site_name' ) ?: get_bloginfo( 'name' ); $local = (bool) Digitalisimo_Integrations_Settings::get( 'seo_local_enabled' ); $checks = array( 'Schema Graph activo' => (bool) Digitalisimo_Integrations_Settings::get( 'seo_schema_enabled' ), 'Organization configurada' => (bool) $org, 'WebSite configurado' => (bool) $site, 'Logo configurado' => (bool) $g( 'seo_logo' ), 'Perfiles oficiales' => Digitalisimo_Integrations_Social_Profiles::configured(), 'Horario local publicado' => ! Digitalisimo_Integrations_Settings::get( 'seo_local_enabled' ) || (bool) Digitalisimo_Integrations_Local_Business::schema_hours(), 'SEO local completo' => ! $local || (bool) ( $g( 'seo_local_city' ) && $g( 'seo_local_country' ) ), 'Nombre local coherente' => ! $local || ! $g( 'seo_local_name' ) || mb_strtolower( $g( 'seo_local_name' ) ) === mb_strtolower( $org ) ); echo '<div class="wrap"><h1>SEO AI · Entidades</h1><p>Reutiliza el Schema Graph existente; no crea AI Schema ni cambia datos.</p><table class="widefat striped"><tr><th>Organization</th><td>' . esc_html( $org ) . '</td></tr><tr><th>Tipo</th><td>' . esc_html( $g( 'seo_organization_type' ) ?: 'Organization' ) . '</td></tr><tr><th>WebSite</th><td>' . esc_html( $site ) . '</td></tr><tr><th>Ubicación</th><td>' . esc_html( trim( $g( 'seo_local_city' ) . ', ' . $g( 'seo_local_region' ) . ', ' . $g( 'seo_local_country' ), ', ' ) ?: 'Sin ubicación' ) . '</td></tr></table><h2>Consistencia</h2><table class="widefat striped">'; foreach ( $checks as $label => $ok ) echo '<tr><th>' . esc_html( $label ) . '</th><td>' . ( $ok ? '✓ Configurado' : '⚠ Revisar' ) . '</td></tr>'; echo '</table><p class="description">IDs esperados: #organization, #website, #webpage y #breadcrumb. Revisa manualmente diferencias de identidad.</p></div>'; }
}
